import{a as e,i as t,r as n,t as r}from"./app-DbTmPHyY.js";var i=JSON.parse(`{"path":"/%E7%AC%AC06%E7%AB%A0%20%E9%A1%B9%E7%9B%AE%E7%AE%A1%E7%90%86%E6%A6%82%E8%AE%BA/6.1%20%E9%A1%B9%E7%9B%AE%E6%A6%82%E5%BF%B5.html","title":"6.1 项目概念","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第06章 项目管理概论/6.1 项目概念.md"}`),a={name:`6.1 项目概念.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_6-1-项目概念" tabindex="-1"><a class="header-anchor" href="#_6-1-项目概念"><span>6.1 项目概念</span></a></h1><h2 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h2><p>项目是为创造<strong>独特产品、服务或成果</strong>而进行的<strong>临时性工作</strong>。</p><h2 id="项目特征" tabindex="-1"><a class="header-anchor" href="#项目特征"><span>项目特征</span></a></h2><h3 id="临时性-temporary" tabindex="-1"><a class="header-anchor" href="#临时性-temporary"><span>临时性（Temporary）</span></a></h3><ul><li>项目有明确的开始和结束时间</li><li>项目不是持续进行的运营活动</li></ul><h3 id="独特性-unique" tabindex="-1"><a class="header-anchor" href="#独特性-unique"><span>独特性（Unique）</span></a></h3><ul><li>每个项目都有独特的产品、服务或成果</li><li>即使是相似的项目，也存在差异</li></ul><h3 id="渐进明细-progressive-elaboration" tabindex="-1"><a class="header-anchor" href="#渐进明细-progressive-elaboration"><span>渐进明细（Progressive Elaboration）</span></a></h3><ul><li>项目的细节随着时间逐渐清晰</li><li>计划和需求逐步完善</li></ul><h3 id="目标导向-goal-oriented" tabindex="-1"><a class="header-anchor" href="#目标导向-goal-oriented"><span>目标导向（Goal-oriented）</span></a></h3><ul><li>项目有明确的目标和可交付成果</li><li>目标完成标志着项目结束</li></ul><h3 id="资源约束-resource-constrained" tabindex="-1"><a class="header-anchor" href="#资源约束-resource-constrained"><span>资源约束（Resource Constrained）</span></a></h3><ul><li>项目受时间、成本、质量等约束</li><li>需要在有限资源内完成目标</li></ul><h2 id="项目与运营的区别" tabindex="-1"><a class="header-anchor" href="#项目与运营的区别"><span>项目与运营的区别</span></a></h2><table><thead><tr><th>维度</th><th>项目</th><th>运营</th></tr></thead><tbody><tr><td><strong>性质</strong></td><td>临时性</td><td>持续性</td></tr><tr><td><strong>目标</strong></td><td>创造独特成果</td><td>维持日常业务</td></tr><tr><td><strong>管理重点</strong></td><td>变更管理</td><td>效率和稳定性</td></tr><tr><td><strong>组织</strong></td><td>项目团队</td><td>职能部门</td></tr></tbody></table><h2 id="项目目标" tabindex="-1"><a class="header-anchor" href="#项目目标"><span>项目目标</span></a></h2><h3 id="项目目标的特点" tabindex="-1"><a class="header-anchor" href="#项目目标的特点"><span>项目目标的特点</span></a></h3><ul><li><strong>具体性</strong>：明确、可衡量</li><li><strong>可实现性</strong>：在约束条件下可完成</li><li><strong>相关性</strong>：与组织战略目标一致</li><li><strong>时效性</strong>：有明确的时间限制</li></ul><h3 id="项目目标的层次" tabindex="-1"><a class="header-anchor" href="#项目目标的层次"><span>项目目标的层次</span></a></h3><ul><li><strong>战略目标</strong>：项目对组织的价值</li><li><strong>交付目标</strong>：项目的可交付成果</li><li><strong>质量目标</strong>：成果的质量要求</li></ul><h2 id="项目成功标准" tabindex="-1"><a class="header-anchor" href="#项目成功标准"><span>项目成功标准</span></a></h2><h3 id="传统标准" tabindex="-1"><a class="header-anchor" href="#传统标准"><span>传统标准</span></a></h3><ul><li>按时完成</li><li>预算内完成</li><li>满足质量要求</li></ul><h3 id="现代标准" tabindex="-1"><a class="header-anchor" href="#现代标准"><span>现代标准</span></a></h3><ul><li>满足客户需求</li><li>实现商业价值</li><li>利益相关方满意</li></ul><h2 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h2><ol><li><strong>项目的定义和特征</strong></li><li><strong>项目与运营的区别</strong></li><li><strong>项目目标的特点</strong></li><li><strong>项目成功标准</strong></li></ol><h2 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h2><p>临时独特渐进目标，项目特征要记牢，运营持续项目临时</p><h2 id="典型例题" tabindex="-1"><a class="header-anchor" href="#典型例题"><span>典型例题</span></a></h2><p><strong>例题</strong>：以下哪项不是项目的特征？ A. 临时性 B. 重复性 C. 独特性 D. 渐进明细</p><p><strong>答案</strong>：B</p><p><strong>解析</strong>：项目的特征包括临时性、独特性、渐进明细和目标导向。重复性是运营的特征，不是项目的特征。</p>`,34)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};